// Edit this object for your run. The Actor's full input schema is linked in the sticky note.
const input = {
  "terms": [
    "ai agents",
    "n8n workflows"
  ],
  "geo": "US",
  "timeRange": "today 3-m",
  "includeRelatedQueries": true
};

return [{ json: input }];

const payload = $input.first().json;
const rows = Array.isArray(payload) ? payload : (payload && (payload.items || payload.data) ? (payload.items || payload.data) : $input.all().map((item) => item.json));
const keyField = "title";
const seen = new Set();

const clean = rows
  .filter((row) => row && typeof row === 'object')
  .map((row) => {
    const out = {};
    for (const [k, v] of Object.entries(row)) {
      if (v === null || v === undefined) continue;
      out[k] = typeof v === 'string' ? v.trim() : v;
    }
    out._source = "https://apify.com/vexaloom-labs/google-trends-interest-and-related-query-scraper";
    out._scrapedAt = new Date().toISOString();
    return out;
  })
  .filter((row) => {
    const value = row[keyField];
    const dedupe = value === undefined || value === null || value === '' ? JSON.stringify(row) : String(value).toLowerCase();
    if (seen.has(dedupe)) return false;
    seen.add(dedupe);
    return true;
  });

return clean.map((json) => ({ json }));
